func (r *NoteSQLiteRepository) where(filter *NoteFilter, args *[]any, includeDeleted bool) string {
	return noteSQLite.where(filter.sqliteConditions(args), includeDeleted)
}

// accessConditions are the filter's conditions, each value appended to
// args, then those that keep the rows to what the operation's caller sees,
// or with write may write (D156, D182): a condition through a relation
// holds the rows it reads to the caller too.
func (r *NoteSQLiteRepository) accessConditions(ctx context.Context, filter *NoteFilter, args *[]any, write bool) []string {
	var conditions []string
	if filter != nil {
		filter.scope = sqliteAccessScopeOf(ctx)
		conditions = filter.sqliteConditions(args)
	}
	return append(conditions, sqliteAccessConditions(ctx, "Note", args, write)...)
}

// accessWhere is where, kept to what the operation's caller sees, or with
// write may write.
func (r *NoteSQLiteRepository) accessWhere(ctx context.Context, filter *NoteFilter, args *[]any, includeDeleted, write bool) string {
	return noteSQLite.where(r.accessConditions(ctx, filter, args, write), includeDeleted)
}

// requireReach returns ErrNotFound unless the row whose key binds as key
// is one the operation's caller sees, or with write may write (D156).
func (r *NoteSQLiteRepository) requireReach(ctx context.Context, key any, write bool) error {
	return sqliteRequireReach(ctx, r.q(), "Note", noteSQLite.quoted, key, write)
}

// requireCreated returns ErrAccessRefused unless a party's or an agent
// run's grants reach every one of rows, the rows a create made (D156).
func (r *NoteSQLiteRepository) requireCreated(ctx context.Context, q sqliteQuerier, rows []*types.Note) error {
	if !accessGranted(ctx) {
		return nil
	}
	keys := make([]any, 0, len(rows))
	for _, row := range rows {
		if row.Id == nil {
			return fmt.Errorf("Note: %w", ErrAccessRefused)
		}
		key, err := noteSQLite.keyArg(*row.Id)
		if err != nil {
			return err
		}
		keys = append(keys, key)
	}
	return sqliteRequireCreated(ctx, q, "Note", noteSQLite.quoted, keys)
}

// orderBy is the ORDER BY of orderBy.
func (r *NoteSQLiteRepository) orderBy(orderBy []NoteOrderBy) string {
	fields := make([]string, len(orderBy))
	desc := make([]bool, len(orderBy))
	for i, order := range orderBy {
		fields[i], desc[i] = string(order.Field), order.Desc
	}
	return noteSQLite.orderBy(fields, desc, NoteQuotedFields)
}

// FindOne retrieves the first Note matching the filter
func (r *NoteSQLiteRepository) FindOne(ctx context.Context, filter *NoteFilter, opts *NoteFindOptions) (*types.Note, error) {
	if opts == nil {
		opts = &NoteFindOptions{}
	}
	var args []any
	where := r.accessWhere(ctx, filter, &args, opts.IncludeDeleted, false)
	record, err := noteSQLite.findOne(ctx, r.q(), where, r.orderBy(opts.OrderBy), args)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, opts.Fields, !opts.Fields.IsZero())
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// FindMany retrieves multiple Note records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *NoteSQLiteRepository) FindMany(ctx context.Context, filter *NoteFilter, opts *NoteFindOptions) ([]*types.Note, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	var args []any
	where := r.accessWhere(ctx, filter, &args, opts.IncludeDeleted, false)
	records, total, err := noteSQLite.findMany(ctx, r.q(), where, r.orderBy(opts.OrderBy), args, opts.Limit, opts.Offset, opts.SkipCount)
	if err != nil {
		return nil, 0, err
	}
	rows, err := r.decode(ctx, records, opts.Fields, true)
	if err != nil {
		return nil, 0, err
	}
	return rows, total, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for another table's read.
func (r *NoteSQLiteRepository) findRelated(ctx context.Context, filter *NoteFilter, opts *NoteFindOptions) ([]*types.Note, error) {
	skip := *opts
	skip.SkipCount = true
	rows, _, err := r.FindMany(ctx, filter, &skip)
	return rows, err
}

// FindPage reads a page of the Note rows filter finds, in the
// sort's order, after the key of the page before (D60, amended).
func (r *NoteSQLiteRepository) FindPage(ctx context.Context, filter *NoteFilter, opts *NotePageOptions) (*NotePage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Note rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = NoteSortById
	}
	column, ok := noteSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Note sorts by id, title, owner, createdAt, audience, agentAccess and effectiveAgents, not %q", string(field))
	}
	var after any
	if opts.After != nil {
		if _, err := opts.After.arg(); err != nil {
			return nil, err
		}
		key, err := noteSQLite.keyArg(opts.After.Id)
		if err != nil {
			return nil, err
		}
		after = key
	}
	var args []any
	conditions := r.accessConditions(ctx, filter, &args, false)
	records, err := noteSQLite.page(ctx, r.q(), conditions, args, sqliteSort{sql: column.sql, key: column.key, nulls: column.nulls}, field == NoteSortById, opts.Sort.Desc, after, limit, opts.IncludeDeleted)
	if err != nil {
		return nil, err
	}
	// Next is the key of the page's last row, so the page reads its
	// primary key whatever Fields selects.
	fields := opts.Fields
	fields.Id = true
	rows, err := r.decode(ctx, records, fields, true)
	if err != nil {
		return nil, err
	}
	page := &NotePage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = notePageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// stampCreate sets the audit fields of who wrote input, as the Postgres
// repository's CreateOne does.
func (r *NoteSQLiteRepository) stampCreate(ctx context.Context, input *types.Note) error {
	return nil
}

// CreateOne inserts a new Note record
func (r *NoteSQLiteRepository) CreateOne(ctx context.Context, input *types.Note) (*types.Note, error) {
	if err := r.stampCreate(ctx, input); err != nil {
		return nil, err
	}
	record, err := sqliteMembersOf(input)
	if err != nil {
		return nil, fmt.Errorf("create Note: %w", err)
	}
	written, err := noteSQLite.insert(ctx, r.q(), record)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{written}, NoteFields{}, false)
	if err != nil {
		return nil, err
	}
	if err := r.requireCreated(ctx, r.q(), rows); err != nil {
		return nil, err
	}
	return rows[0], nil
}

// CreateMany inserts the rows in the inputs' order and returns them, in one
// transaction: a statement per run of consecutive rows that write the same
// columns, since a VALUES list on SQLite takes no DEFAULT, of at most 4095
// rows, as many as SQLite binds the parameters of (sqliteTable.insertMany).
func (r *NoteSQLiteRepository) CreateMany(ctx context.Context, inputs []*types.Note) ([]*types.Note, error) {
	out := make([]*types.Note, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	records := make([]sqliteRecord, len(inputs))
	for i, input := range inputs {
		if err := r.stampCreate(ctx, input); err != nil {
			return nil, err
		}
		record, err := sqliteMembersOf(input)
		if err != nil {
			return nil, fmt.Errorf("create Note %d: %w", i, err)
		}
		records[i] = record
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		written, err := noteSQLite.insertMany(ctx, q, records, 4095)
		if err != nil {
			return err
		}
		rows, err := r.decode(ctx, written, NoteFields{}, false)
		if err != nil {
			return err
		}
		// A row the caller's grants do not reach rolls the whole create
		// back (D156).
		if err := r.requireCreated(ctx, q, rows); err != nil {
			return err
		}
		out = append(out, rows...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// sets are update's assignments, each value appended to args after those
// already there, and the columns they set and their values, which an
// upsert only if changed compares (D89).
func (r *NoteSQLiteRepository) sets(update *NoteUpdate, args *[]any) (sets, compare, next []string, err error) {
	if update == nil {
		return nil, nil, nil, nil
	}
	if update.Title != nil {
		value, err := noteSQLite.arg(*update.Title, 1)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`title = ?%d`, len(*args)))
		compare, next = append(compare, `note.title`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.Owner != nil {
		value, err := noteSQLite.arg(*update.Owner, 2)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`"owner" = ?%d`, len(*args)))
		compare, next = append(compare, `note."owner"`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.Audience != nil {
		value, err := noteSQLite.arg(*update.Audience, 4)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`audience = ?%d`, len(*args)))
		compare, next = append(compare, `note.audience`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.AudienceNamed != nil && update.AudienceNamedSetNull {
		return nil, nil, nil, fmt.Errorf("audience_named cannot be updated with both value and null assignment")
	}
	if update.AudienceNamedSetNull {
		sets = append(sets, `audience_named = NULL`)
		compare, next = append(compare, `note.audience_named`), append(next, `NULL`)
	} else if update.AudienceNamed != nil {
		value, err := noteSQLite.arg(*update.AudienceNamed, 5)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`audience_named = ?%d`, len(*args)))
		compare, next = append(compare, `note.audience_named`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.AgentAccess != nil {
		value, err := noteSQLite.arg(*update.AgentAccess, 6)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`agent_access = ?%d`, len(*args)))
		compare, next = append(compare, `note.agent_access`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.EffectiveAudience != nil && update.EffectiveAudienceSetNull {
		return nil, nil, nil, fmt.Errorf("effective_audience cannot be updated with both value and null assignment")
	}
	if update.EffectiveAudienceSetNull {
		sets = append(sets, `effective_audience = NULL`)
		compare, next = append(compare, `note.effective_audience`), append(next, `NULL`)
	} else if update.EffectiveAudience != nil {
		value, err := noteSQLite.arg(*update.EffectiveAudience, 7)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`effective_audience = ?%d`, len(*args)))
		compare, next = append(compare, `note.effective_audience`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.EffectiveAgents != nil {
		value, err := noteSQLite.arg(*update.EffectiveAgents, 8)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`effective_agents = ?%d`, len(*args)))
		compare, next = append(compare, `note.effective_agents`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	return sets, compare, next, nil
}

// updatedBy is who an update says it was made by: its own UpdatedBy, the
// acting user, or nil.
func (r *NoteSQLiteRepository) updatedBy(ctx context.Context, update *NoteUpdate) (any, error) {
	return nil, nil
}

// stamped are sets with the stamps of an update after them and each
// fence they advance (D119).
func (r *NoteSQLiteRepository) stamped(ctx context.Context, update *NoteUpdate, sets []string, args []any) ([]string, []any, error) {
	by, err := r.updatedBy(ctx, update)
	if err != nil {
		return nil, nil, err
	}
	sets, args = noteSQLite.stamp(sets, args, by)
	return sets, args, nil
}

// UpdateOne sets the members update sets on the live row whose key is id.
func (r *NoteSQLiteRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *NoteUpdate) (*types.Note, error) {
	return r.updateOne(ctx, id, update, nil)
}

func (r *NoteSQLiteRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *NoteUpdate, version *int64) (*types.Note, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return nil, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return nil, err
	}
	if len(sets) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}
	key, err := noteSQLite.keyArg(id)
	if err != nil {
		return nil, err
	}
	if err := r.requireReach(ctx, key, true); err != nil {
		return nil, err
	}
	record, err := noteSQLite.update(ctx, r.q(), key, sets, args, version)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, NoteFields{}, false)
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// UpdateMany sets the members update sets on the live rows filter finds,
// and answers how many.
func (r *NoteSQLiteRepository) UpdateMany(ctx context.Context, filter *NoteFilter, update *NoteUpdate) (int, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return 0, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return 0, err
	}
	if len(sets) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}
	where := r.accessWhere(ctx, filter, &args, false, true)
	n, err := noteSQLite.exec(ctx, r.q(), fmt.Sprintf(noteSQLite.st.updateMany, strings.Join(sets, ", "), where), args...)
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}
	return n, nil
}

// deletedBy is the acting user a delete stamps, and ErrNoUserInContext
// without one on a table that stamps it.
func (r *NoteSQLiteRepository) deletedBy(ctx context.Context) (any, error) {
	return nil, nil
}

// DeleteOne deletes the live row whose key is id.
func (r *NoteSQLiteRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	return r.deleteOne(ctx, id, nil)
}

func (r *NoteSQLiteRepository) deleteOne(ctx context.Context, id types.IdentityUUID, version *int64) error {
	by, err := r.deletedBy(ctx)
	if err != nil {
		return err
	}
	key, err := noteSQLite.keyArg(id)
	if err != nil {
		return err
	}
	if err := r.requireReach(ctx, key, true); err != nil {
		return err
	}
	return noteSQLite.deleteOne(ctx, r.q(), key, by, version)
}

// DeleteMany deletes the live rows filter finds, and
// answers how many.
func (r *NoteSQLiteRepository) DeleteMany(ctx context.Context, filter *NoteFilter) (int, error) {
	by, err := r.deletedBy(ctx)
	if err != nil {
		return 0, err
	}
	return noteSQLite.deleteMany(ctx, r.q(), func(args *[]any) []string { return r.accessConditions(ctx, filter, args, true) }, by)
}

// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead (D79).
func (r *NoteSQLiteRepository) UpsertOne(ctx context.Context, input *types.Note, on NoteUniqueKey, update *NoteUpdate) (*types.Note, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with its row (D89).
func (r *NoteSQLiteRepository) UpsertOneResult(ctx context.Context, input *types.Note, on NoteUniqueKey, update *NoteUpdate, opts *UpsertOptions) (UpsertResult[*types.Note], error) {
	if err := refuseHeldUpsert(ctx, "UpsertOne", "Note"); err != nil {
		return UpsertResult[*types.Note]{}, err
	}
	key, ok := noteSQLiteUniqueKeys[on]
	if !ok {
		return UpsertResult[*types.Note]{}, fmt.Errorf("orm: Note has no unique key %q", string(on))
	}
	onlyIfChanged := opts != nil && opts.OnlyIfChanged
	var out UpsertResult[*types.Note]
	err := r.within(ctx, func(q sqliteQuerier) error {
		if err := r.stampCreate(ctx, input); err != nil {
			return err
		}
		record, err := sqliteMembersOf(input)
		if err != nil {
			return fmt.Errorf("upsert Note: %w", err)
		}
		var args []any
		sets, compare, next, err := r.sets(update, &args)
		if err != nil {
			return err
		}
		if len(sets) > 0 {
			if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
				return err
			}
		}
		upserted, err := noteSQLite.upsert(ctx, q, record, key, sets, args, compare, next, onlyIfChanged)
		if err != nil {
			return err
		}
		rows, err := r.decode(ctx, []sqliteRecord{upserted.record}, NoteFields{}, false)
		if err != nil {
			return err
		}
		out = UpsertResult[*types.Note]{Row: rows[0], Status: upserted.status}
		return nil
	})
	return out, err
}

// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it
// did with it, in the inputs' order (D89): sqlutil's SQLite upsert, a batch
// of opts.Batch rows or as many as SQLite binds the parameters of, in one
// transaction, which the rows that hold each batch's keys are read in
// before and after it (sqliteTable.upsertMany). One whose update names no
// field updates nothing, and reads each row a key holds back. Two inputs of one batch that hold one key are refused,
// with Postgres's SQLSTATE 21000, and a key over an expression is refused.
func (r *NoteSQLiteRepository) UpsertMany(ctx context.Context, inputs []*types.Note, on NoteUniqueKey, update NoteFields, opts *UpsertOptions) ([]UpsertResult[*types.Note], error) {
	if err := refuseHeldUpsert(ctx, "UpsertMany", "Note"); err != nil {
		return nil, err
	}
	key, ok := noteSQLiteUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: Note has no unique key %q", string(on))
	}
	if key.expression {
		return nil, upsertExpressionKey("UpsertMany", "Note", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of Note sets the fields an update sets, not id")
	}
	if update.CreatedAt {
		return nil, fmt.Errorf("orm: UpsertMany of Note sets the fields an update sets, not createdAt")
	}
	batch, err := upsertBatch("Note", opts.Batch, 4095)
	if err != nil {
		return nil, err
	}
	out := make([]UpsertResult[*types.Note], 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	// The columns update names, a relation by its key's column.
	named := noteSQLiteMembers(update)
	var set []int
	for i := range noteSQLite.columns {
		if c := &noteSQLite.columns[i]; named[c.member] && !c.key && !c.auto {
			set = append(set, i)
		}
	}
	err = r.within(ctx, func(q sqliteQuerier) error {
		records := make([]sqliteRecord, len(inputs))
		for i, input := range inputs {
			if err := r.stampCreate(ctx, input); err != nil {
				return err
			}
			record, err := sqliteMembersOf(input)
			if err != nil {
				return fmt.Errorf("upsert Note %d: %w", i, err)
			}
			records[i] = record
		}
		upserted, err := noteSQLite.upsertMany(ctx, q, records, key, string(on), set, batch, opts.OnlyIfChanged, func(sets []string, args []any) ([]string, []any, error) {
			return r.stamped(ctx, nil, sets, args)
		})
		if err != nil {
			return err
		}
		written := make([]sqliteRecord, len(upserted))
		for i, u := range upserted {
			written[i] = u.record
		}
		rows, err := r.decode(ctx, written, NoteFields{}, false)
		if err != nil {
			return err
		}
		for i, row := range rows {
			out = append(out, UpsertResult[*types.Note]{Row: row, Status: upserted[i].status})
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}
